% Decision variable: steps taken at each move (0 means no steps after reaching the top)
array[1..20] of var 0..5: steps;

% Each step must be 0, 3, 4, or 5
constraint forall(i in 1..20)(steps[i] in {0, 3, 4, 5});

% First move cannot be 0
constraint steps[1] != 0;

% Once a 0 appears, all subsequent steps must be 0
constraint forall(i in 1..19)(steps[i] == 0 -> steps[i+1] == 0);

% Total steps must sum exactly to 20
constraint sum(steps) == 20;

solve satisfy;

% Output the steps array in JSON format
output ["{\"steps\": ", show(steps), "}"];
```

