% Age values: 3, 5, 7, 8, 10 (indices 1-5)
array[1..5] of int: AGE_VALUES = [3, 5, 7, 8, 10];
% Countries: Ethiopia(1), Kazakhstan(2), Lithuania(3), Morocco(4), Yemen(5)
% Stories: burning_bush(1), captivity(2), moses_youth(3), passover(4), ten_commandments(5)

% Decision variables (each child's attribute as index in their category)
array[1..5] of var 1..5: age;      % Age index for each child (Bernice, Carl, Debby, Sammy, Ted)
array[1..5] of var 1..5: country;  % Country index for each child
array[1..5] of var 1..5: story;    % Story index for each child

% All attributes must be permutations
constraint all_different(age) /\ all_different(country) /\ all_different(story);

% 1. Debby’s family is from Lithuania (country index 3)
constraint country[3] == 3;

% 2. Passover child (story=4) is 2 years older than Bernice (child 1)
constraint exists(i in 1..5) (
    story[i] == 4 
    /\ (AGE_VALUES[age[i]] == AGE_VALUES[age[1]] + 2)
);

% 3. Yemen (country=5) is younger than Ethiopia (country=1)
constraint exists(i, j in 1..5 where country[i] == 5 /\ country[j] == 1) (
    AGE_VALUES[age[i]] < AGE_VALUES[age[j]]
);

% 4. Morocco (country=4) is 3 years older than Ted (child 5)
constraint exists(i in 1..5 where country[i] == 4) (
    AGE_VALUES[age[i]] == AGE_VALUES[age[5]] + 3
);

% 5. Sammy (child4) is 3 years older than Moses’s youth (story=3) child
constraint exists(j in 1..5 where story[j] == 3) (
    AGE_VALUES[age[4]] == AGE_VALUES[age[j]] + 3
);

solve satisfy;

% Output the lists as JSON with keys: ages, children, countries, stories
output [
    "{",
    join(",", [
        "\"ages\": " ++ show(age),
        "\"children\": [1, 2, 3, 4, 5]",
        "\"countries\": " ++ show(country),
        "\"stories\": " ++ show(story)
    ]),
    "}"
];
```

