include "globals.mzn";

int: n = 8;
array[1..n] of array[1..3] of int: adjacency_list = [
    [2,3,7],
    [1,4,8],
    [1,4,5],
    [2,3,6],
    [3,6,7],
    [4,5,8],
    [1,5,8],
    [2,6,7]
];

array[1..n] of var bool: nodes;

% Independent set constraints: No two adjacent nodes are selected
constraint forall(i in 1..n) (
    forall(j in adjacency_list[i]) (
        nodes[i] -> (not nodes[j])
    )
);

% Maximality constraints: Unselected nodes have at least one selected neighbor
constraint forall(i in 1..n) (
    nodes[i] \/ (sum(j in adjacency_list[i])(nodes[j]) >= 1
);

solve satisfy;

output [
    "{",
    "\"nodes\": ", show([bool2int(nodes[i]) | i in 1..n]),
    "}"
];
```

