include "globals.mzn";

% Input data
int: n = 9;
array[1..n, 1..3] of string: movies = [
    ["Tarjan of the Jungle", 4, 13],
    ["The Four Volume Problem", 17, 27],
    ["The President's Algorist", 1, 10],
    ["Steiner's Tree", 12, 18],
    ["Process Terminated", 23, 30],
    ["Halting State", 9, 16],
    ["Programming Challenges", 19, 25],
    ["Discrete Mathematics", 2, 7],
    ["Calculated Bets", 26, 31]
];

% Extract start and end times
array[1..n] of int: start = [movies[i,2] | i in 1..n];
array[1..n] of int: end = [movies[i,3] | i in 1..n];

% Decision Variables: 1 if movie is selected, 0 otherwise
array[1..n] of var 0..1: selected_movies;

% Constraints: No overlapping intervals for selected movies
constraint forall(i, j in 1..n where i < j) (
    (selected_movies[i] == 1 /\ selected_movies[j] == 1) 
    -> 
    (end[i] <= start[j] \/ end[j] <= start[i])
);

% Objective: Maximize number of selected movies
solve maximize sum(selected_movies);

% Output results in specified JSON format
output [
    "{",
    join(",", [
        "\"" ++ "num_selected_movies" ++ "\": " ++ show(sum(selected_movies)),
        "\"" ++ "selected_movies" ++ "\": [" ++ join(",", [show(selected_movies[i]) | i in 1..n]) ++ "]"
    ]),
    "}"
];
