var bool: artie;
var bool: bill;
var bool: crackitt;
var bool: dodgy;
var bool: edgy;
var bool: fingers;

var int: sum_guilty = artie + bill + crackitt + dodgy + edgy + fingers;

% At least four innocent (max two guilty)
constraint sum_guilty <= 2;

% Bill's statement: Crackitt was guilty (truth if innocent, lie if guilty)
constraint crackitt == not bill;

% Dodgy's statement: If Crackitt did it, Bill did it with him
constraint if dodgy then (crackitt /\ (not bill)) else (crackitt -> bill);

% Edgy's statement: Nobody did it alone (truth if innocent: sum >=2; lie if guilty: sum <2)
constraint (not edgy) -> (sum_guilty >= 2);
constraint edgy -> (sum_guilty < 2);

% Fingers' statement: Artie and Dodgy together did it (truth if innocent, lie if guilty)
constraint (not fingers) -> (
    artie /\ dodgy /\ (not bill) /\ (not crackitt) /\ (not edgy)
);

solve satisfy;

output [
    "{",
