        "\"artie\": " ++ show(artie),
        "\"bill\": " ++ show(bill),
        "\"crackitt\": " ++ show(crackitt),
        "\"dodgy\": " ++ show(dodgy),
        "\"edgy\": " ++ show(edgy),
        "\"fingers\": " ++ show(fingers)
    ]),
    "}"
];
