array[1..3, 1..3] of int: puzzle_end = [|1,2,3 |4,5,6 |7,8,0|];

% Decision Variables
array[0..N, 1..3, 1..3] of var 0..8: steps;
array[0..N] of var 1..3: row;
array[0..N] of var 1..3: col;

% Fix initial and final states
constraint forall(i in 1..3, j in 1..3) (
    steps[0, i, j] = puzzle_start[i, j]
);
constraint forall(i in 1..3, j in 1..3) (
    steps[N, i, j] = puzzle_end[i, j]
);

% Ensure valid puzzle state for each step
constraint forall(t in 0..N) (
    steps[t, row[t], col[t]] = 0
);
constraint forall(t in 0..N) (
    count([steps[t, i, j] | i in 1..3, j in 1..3], 0) = 1
);
constraint forall(t in 0..N) (
    alldifferent_except_0([steps[t, i, j] | i in 1..3, j in 1..3])
);

% Transition constraints between consecutive steps
constraint forall(t in 0..N-1) (
    abs(row[t+1] - row[t]) + abs(col[t+1] - col[t]) = 1
);
constraint forall(t in 0..N-1, i in 1..3, j in 1..3) (
    steps[t+1, i, j] = 
        if i = row[t] /\ j = col[t] then
            steps[t, row[t+1], col[t+1]]
        elseif i = row[t+1] /\ j = col[t+1] then
            0
        else
            steps[t, i, j]
        endif
);

solve satisfy;

% Output the solution in JSON format
output [
    "{\"steps\": ["
