int: stage = 8;  % Number of stages (0..stage inclusive)

% Decision Variables - positions at each stage (0=start, 1=dest)
array[0..stage] of var 0..1: wolf_pos;
array[0..stage] of var 0..1: goat_pos;
array[0..stage] of var 0..1: cabbage_pos;
array[0..stage] of var 0..1: boat_pos;

% Initial state - all on start shore
constraint wolf_pos[0] == 0 /\ goat_pos[0] == 0 /\ cabbage_pos[0] == 0 /\ boat_pos[0] == 0;

% Final state - all on destination shore
constraint wolf_pos[stage] == 1 /\ goat_pos[stage] == 1 /\ cabbage_pos[stage] == 1 /\ boat_pos[stage] == 1;

% Safety constraints (no dangerous pairs left unattended)
predicate safe(int: i) =
    let { 0..1: farmer_shore = boat_pos[i] } in
    not ((wolf_pos[i] != farmer_shore) /\ (goat_pos[i] != farmer_shore)) /\  % Wolf & goat can't be alone
    not ((goat_pos[i] != farmer_shore) /\ (cabbage_pos[i] != farmer_shore)); % Goat & cabbage can't be alone

% Transition constraints between stages
predicate valid_move(int: from, int: to) =
    let {
        % Boat must flip position each move
        constraint boat_pos[to] == 1 - boat_pos[from],

        % Count how many items changed position
        var int: moves = sum([wolf_pos[to] != wolf_pos[from],
                             goat_pos[to] != goat_pos[from],
                             cabbage_pos[to] != cabbage_pos[from]])
    } in
    % Max 1 item moved per transition and item must be on same shore as boat
    moves <= 1 /\
    (wolf_pos[to] != wolf_pos[from] -> (wolf_pos[from] == boat_pos[from])) /\
    (goat_pos[to] != goat_pos[from] -> (goat_pos[from] == boat_pos[from])) /\
    (cabbage_pos[to] != cabbage_pos[from] -> (cabbage_pos[from] == boat_pos[from]));

% Apply constraints
constraint forall(i in 0..stage)(safe(i)) /\
          forall(i in 0..stage-1)(valid_move(i, i+1));

solve satisfy;

% Output in JSON format with specified keys
output [
    "{",
    join(",", [
        "\"wolf_pos\": " ++ show(wolf_pos),
        "\"goat_pos\": " ++ show(goat_pos),
        "\"cabbage_pos\": " ++ show(cabbage_pos),
        "\"boat_pos\": " ++ show(boat_pos)
    ]),
    "}"
];
