int: deck_width;
int: deck_length;
int: n_containers;
array[1..n_containers] of int: width;
array[1..n_containers] of int: length;
array[1..n_containers] of int: classes;
array[1..2, 1..2] of int: separation;

array[1..n_containers] of var 0..deck_width: left;
array[1..n_containers] of var 0..deck_length: bottom;
array[1..n_containers] of var int: right = [left[i] + width[i] | i in 1..n_containers];
array[1..n_containers] of var int: top = [bottom[i] + length[i] | i in 1..n_containers];

constraint forall(i in 1..n_containers) (
    right[i] <= deck_width /\ top[i] <= deck_length
);

constraint forall(i in 2..n_containers) (
    (left[i] = 0) \/ exists(j in 1..i-1)(right[j] = left[i])
);

constraint forall(i in 2..n_containers) (
    (top[i] = deck_length) \/ exists(j in 1..i-1)(bottom[j] = top[i])
);

constraint forall(i in 1..n_containers, j in i+1..n_containers) (
    let {
        int: c_i = classes[i],
        int: c_j = classes[j],
        int: s = separation[c_i, c_j]
    } in
    ( (right[i] + s <= left[j]) \/ (right[j] + s <= left[i]) \/ (top[i] + s <= bottom[j]) \/ (top[j] + s <= bottom[i]) )
);

solve satisfy;

output [
    "{\n",
    "  \"left\": ", show(left), ",\n",
    "  \"right\": ", show(right), ",\n",
    "  \"top\": ", show(top), ",\n",
    "  \"bottom\": ", show(bottom), "\n",
    "}"
];
