% Input data
int: base = 6;
array[int] of int: sides = [3, 3, 3, 2, 1, 1, 1, 1, 1];
int: n = length(sides);

% Decision Variables: coordinates of the bottom-left corner of each square
array[1..n] of var int: x_coords;
array[1..n] of var int: y_coords;

% Constraints to ensure squares fit within the base square
constraint forall(i in 1..n) (
    x_coords[i] >= 0 /\ 
    x_coords[i] + sides[i] <= base /\
    y_coords[i] >= 0 /\
    y_coords[i] + sides[i] <= base
);

% Sum of areas must match the base square area
constraint sum([sides[i]^2 | i in 1..n]) = base^2;

% Non-overlapping constraints for all pairs of squares
constraint forall(i, j in 1..n where i < j) (
    (x_coords[i] + sides[i] <= x_coords[j]) \/  % i left of j
    (x_coords[j] + sides[j] <= x_coords[i]) \/  % j left of i
    (y_coords[i] + sides[i] <= y_coords[j]) \/  % i below j
    (y_coords[j] + sides[j] <= y_coords[i])     % j below i
);

solve satisfy;

% Output the coordinates in JSON format
output [
    "{",
    "\"x_coords\": ", show(x_coords), ", ",
    "\"y_coords\": ", show(y_coords),
    "}"
];
