include "globals.mzn";

int: n_weeks = 4;
int: n_groups = 3;
int: group_size = 3;
int: n_golfers = n_groups * group_size;

set of int: Weeks = 1..n_weeks;
set of int: Groups = 1..n_groups;
set of int: Golfers = 1..n_golfers;
set of int: Positions = 1..group_size;

array[Weeks, Groups, Positions] of var Golfers: assign;

% Ensure groups are sorted within each week to break symmetries
constraint forall (w in Weeks, g in Groups) (
    assign[w, g, 1] < assign[w, g, 2] 
    /\ 
    assign[w, g, 2] < assign[w, g, 3]
);

% All golfers participate exactly once per week
constraint forall (w in Weeks) (
    all_different([assign[w, g, p] | g in Groups, p in Positions])
);

% No two golfers are in the same group more than once
constraint forall (a, b in Golfers where a < b) (
    sum([bool2int(
        exists(g in Groups) (
            (a == assign[w, g, 1] \/ a == assign[w, g, 2] \/ a == assign[w, g, 3]) 
            /\ 
            (b == assign[w, g, 1] \/ b == assign[w, g, 2] \/ b == assign[w, g, 3])
        )
    ) | w in Weeks]) == 1
);

solve satisfy;

output ["{\"assign\": ", show(assign), "}"];
```

