include "regular.mzn";

int: rows = 8;
int: cols = 13;
array[1..rows, 1..cols] of var 0..1: board;

array[1..rows] of array[int] of int: row_rules = [
    [1],    % Original [0,1]
    [2],    % Original [0,2]
    [4,4],
    [12],   % Original [0,12]
    [8],    % Original [0,8]
    [9],    % Original [0,9]
    [3,4],
    [2,2]
];

array[1..cols] of array[int] of int: col_rules = [
    [2],    % Original [0,2]
    [2,1],
    [3,2],
    [6],    % Original [0,6]
    [1,4],
    [3],    % Original [0,3]
    [4],    % Original [0,4]
    [4],
    [4],
    [5],    % Original [0,5]
    [4],
    [1,3],
    [2]     % Original [0,2]
];

predicate nonogram_rule(array[int] of var 0..1: x, array[int] of int: blocks) = 
    if length(blocks) == 0 then
        forall(i in index_set(x))(x[i] == 0)
    else
        let {
            int: n_states = 1 + sum(blocks) + length(blocks),
            array[1..n_states, 0..1] of int: trans,
            int: start_state = 1,
            set of int: accepting_states = {n_states}
        } in
        regular(x, n_states, 2, trans, start_state, accepting_states)
        where {
            % Initialize transitions to 0 (invalid)
            forall(s in 1..n_states, v in 0..1)(trans[s,v] = 0),
            % Initial state transitions
            trans[1,0] = 1;
            trans[1,1] = 2;
            int: curr = 2;
            forall(i in 1..length(blocks)) (
                % Block states
                forall(j in 1..blocks[i]-1)(
                    trans[curr+j-1,1] = curr+j
                ),
                trans[curr+blocks[i]-1,1] = curr+blocks[i],
                % Gap after block
                if i < length(blocks) then
                    trans[curr+blocks[i],0] = curr+blocks[i]+1,
                    trans[curr+blocks[i]+1,0] = curr+blocks[i]+1,
                    trans[curr+blocks[i]+1,1] = curr+blocks[i]+2,
                    curr := curr+blocks[i]+2
                else
                    trans[curr+blocks[i],0] = n_states,
                    curr := curr+blocks[i]
                endif
            ),
            % Accepting state loop
            trans[n_states,0] = n_states
        };

constraint forall(r in 1..rows)(
    nonogram_rule([board[r,c] | c in 1..cols], row_rules[r])
);

constraint forall(c in 1..cols)(
    nonogram_rule([board[r,c] | r in 1..rows], col_rules[c])
);

solve satisfy;

output [
    "{\"board\": "++show([ [fix(board[r,c]) | c in 1..cols ] | r in 1..rows])++"}"
];
```

