include "globals.mzn";

int: n_boats = 5;
int: n_periods = 4;
array[1..n_boats] of int: capacity = [6, 8, 12, 12, 12];
array[1..n_boats] of int: crew_size = [2, 2, 2, 2, 4];

array[1..n_boats] of var bool: is_host;
array[1..n_boats, 1..n_periods] of var 1..n_boats: visits;

% Hosts stay on their boat in all periods
constraint forall(b in 1..n_boats, p in 1..n_periods)(
    is_host[b] -> (visits[b, p] == b)
);

% Guest visits must be to hosts
constraint forall(b in 1..n_boats, p in 1..n_periods)(
    if not is_host[b] then is_host[visits[b, p]] else true endif
);

% Guests must visit different hosts each period
constraint forall(b in 1..n_boats)(
    if not is_host[b] then all_different([visits[b, p] | p in 1..n_periods]) else true endif
);

% Capacity constraints
constraint forall(h in 1..n_boats, p in 1..n_periods)(
    is_host[h] -> (
        sum(g in 1..n_boats where not is_host[g])( (visits[g, p] == h) * crew_size[g] ) + crew_size[h] <= capacity[h]
    )
);

% Guest crews cannot meet more than once
constraint forall(g1, g2 in 1..n_boats where g1 < g2)(
    (not is_host[g1] /\ not is_host[g2]) -> (
        sum(p in 1..n_periods)(visits[g1, p] == visits[g2, p]) <= 1
    )
);

solve minimize sum(is_host);

output [
    "{",
    join(",", [
        "\"is_host\": " ++ show(is_host),
        "\"visits\": [" ++
            join(",", [
                "[" ++ join(",", [show(visits[b, p]) | p in 1..n_periods]) ++ "]"
                | b in 1..n_boats
            ]) ++
        "]"
    ]),
    "}"
];
