include "globals.mzn";

int: n_teams = 8;
int: weeks = 14;
int: periods = 4;
int: half_weeks = weeks div 2;

array[1..weeks, 1..periods] of var 0..n_teams-1: home;
array[1..weeks, 1..periods] of var 0..n_teams-1: away;

% Mirror the second half of weeks
constraint forall(w in 1..half_weeks, p in 1..periods) (
    home[half_weeks + w, p] == away[w, p] /\
    away[half_weeks + w, p] == home[w, p]
);

% All teams play exactly once per week (home or away)
constraint forall(w in 1..weeks) (
    all_different([home[w, p] | p in 1..periods] ++ [away[w, p] | p in 1..periods])
);

% Each pair plays once in each direction (handled by mirroring)
constraint forall(i in 0..n_teams-1, j in 0..n_teams-1 where i < j) (
    sum([bool2int((home[w,p] == i /\ away[w,p] == j) \/ (home[w,p] == j /\ away[w,p] == i)) | w in 1..half_weeks, p in 1..periods]) == 1
);

% No team plays against itself
constraint forall(w in 1..weeks, p in 1..periods) (
    home[w,p] != away[w,p]
);

% Each team appears at most once per period in first half (total <=2 with mirror)
constraint forall(p in 1..periods, t in 0..n_teams-1) (
    sum([bool2int(home[w,p] == t \/ away[w,p] == t) | w in 1..half_weeks]) <= 1
);

solve satisfy;

output [
    "{\n",
    "\"home\": ", show(home), ",\n",
    "\"away\": ", show(away), "\n",
    "}"
];
```

