% BIBD parameters
int: v = 9;  % Number of objects
int: b = 12;  % Number of blocks
int: r = 4;   % Each object in r blocks
int: k = 3;   % Each block contains k objects
int: l = 1;   % Each pair in l blocks

% Incidence matrix: rows=objects, columns=blocks
array[1..v, 1..b] of var 0..1: matrix;

% Row constraints: each object appears in exactly r blocks
constraint forall(i in 1..v) (
    sum([matrix[i, j] | j in 1..b]) = r
);

% Column constraints: each block contains exactly k objects
constraint forall(j in 1..b) (
    sum([matrix[i, j] | i in 1..v]) = k
);

% Pair constraints: every pair appears in exactly l blocks
constraint forall(i1, i2 in 1..v where i1 < i2) (
    sum([matrix[i1, j] * matrix[i2, j] | j in 1..b]) = l
);

solve satisfy;

% Output JSON with incidence matrix
output [
    "{\n",
    "  \"matrix\": [\n",
    join(",\n", [ 
        "    [" ++ join(", ", [show(matrix[i, j]) | j in 1..b]) ++ "]" 
        | i in 1..v 
    ]),
    "\n  ]\n}"
];
```

