include "globals.mzn";

int: n = 10;

% Degree sequence (non-increasing)
array[1..n] of var 3..9: d;

% Adjacency matrix (symmetric, no loops)
array[1..n, 1..n] of var 0..1: adj;

% Each degree is a multiple of 3 and positive
constraint forall(i in 1..n)(d[i] mod 3 == 0);
constraint forall(i in 1..n)(d[i] > 0);

% Sum of degrees is divisible by 12 (sum mod 12 = 0)
constraint sum(d) mod 12 == 0;

% Non-increasing degree sequence
constraint forall(i in 1..n-1)(d[i] >= d[i+1]);

% Adjacency matrix constraints (symmetric, no loops)
constraint forall(i in 1..n)(adj[i,i] == 0);
constraint forall(i, j in 1..n where i < j)(adj[i,j] == adj[j,i]);

% Degree matches sum of edges for each vertex
constraint forall(i in 1..n)(
    sum([adj[i,j] | j in 1..n where j != i]) == d[i]
);

% Diamond-free: no 4-clique with 5 edges
constraint forall(a, b, c, d in 1..n where a < b /\ b < c /\ c < d)(
    adj[a,b] + adj[a,c] + adj[a,d] + adj[b,c] + adj[b,d] + adj[c,d] <= 4
);

solve satisfy;

% Output the adjacency matrix in JSON format
output [
    "{",
    "\"matrix\": [",
    join(",\n ", [
        "[" ++ join(", ", [show(adj[i,j]) | j in 1..n]) ++ "]" 
        | i in 1..n
    ]),
    "]",
    "}"
];
