output [
    "{",
    join(",", [
        "\"" ++ "x" ++ "\": " ++ show([ [fix(x[i,j]) | j in 1..n ] | i in 1..n ]),
        "\"" ++ "z" ++ "\": " ++ show(z)
    ]),
    "}"
];
