include "globals.mzn";

% Input data
array[1..4] of string: warehouse_s = ["New York", "Los Angeles", "Chicago", "Atlanta"];
array[1..4] of int: fixed_costs = [400, 500, 300, 150];
int: max_shipping = 100;
array[1..3] of int: demands = [80, 70, 40];
array[1..4, 1..3] of int: shipping_costs = [
    [20, 40, 50],
    [48, 15, 26],
    [26, 35, 18],
    [24, 50, 35]
];

% Decision Variables
array[1..4] of var bool: open_warehouse;
array[1..4, 1..3] of var 0..max_shipping: ships;

% Total cost calculation
var int: total_cost = sum([fixed_costs[i] * bool2int(open_warehouse[i]) | i in 1..4]) 
                     + sum([shipping_costs[i, j] * ships[i, j] | i in 1..4, j in 1..3]);

% Constraints
constraint open_warehouse[1] -> open_warehouse[2];  % NY implies LA
constraint sum([bool2int(open_warehouse[i]) | i in 1..4]) <= 3;  % Max 3 open
constraint open_warehouse[2] \/ open_warehouse[4];  % LA or Atlanta

% Shipping constraints: closed warehouses cannot ship
constraint forall(i in 1..4, j in 1..3) (
    ships[i, j] <= max_shipping * bool2int(open_warehouse[i])
);

% Demand satisfaction
constraint forall(j in 1..3) (
    sum([ships[i, j] | i in 1..4]) == demands[j]
);

% Solve to minimize total cost
solve minimize total_cost;

% Output in JSON format
output [
    "{\n",
    "\"total_cost\": ", show(total_cost), ",\n",
    "\"open_warehouse\": ", show([bool2int(open_warehouse[i]) | i in 1..4]), ",\n",
    "\"ships\": ", show(ships), "\n",
    "}"
];
```

