% Input data
int: num_moves = 3;
array[1..3] of int: init = [1, 0, 1];

% Decision Variables: Steps representing which coin to flip each move (1..3)
array[1..num_moves] of var 1..3: steps;

% Calculate flip counts for each coin
var int: count1 = sum([steps[i] == 1 | i in 1..num_moves]);
var int: count2 = sum([steps[i] == 2 | i in 1..num_moves]);
var int: count3 = sum([steps[i] == 3 | i in 1..num_moves]);

% Final state after flips (0..1 for each coin)
var 0..1: final1 = (init[1] + count1) mod 2;
var 0..1: final2 = (init[2] + count2) mod 2;
var 0..1: final3 = (init[3] + count3) mod 2;

% All coins must be heads or all tails in the final state
constraint all_equal([final1, final2, final3]);

solve satisfy;

% Output steps as JSON array
output [
    "{",
    "\"steps\": [", 
    join(",", [show(steps[i]) | i in 1..num_moves]), 
    "]",
    "}"
];
